    // ---- user code (project.userCode) ----
    {const V = {"trail0":{"1":15,"2":1,"3":2,"4":3,"5":4,"6":5,"7":6,"8":7,"9":8,"10":9,"11":10,"12":11,"13":12,"14":13,"15":14,"__blank":0},"trail15":{"1":15,"2":1,"3":2,"4":3,"5":4,"6":5,"7":6,"8":7,"9":8,"10":9,"11":10,"12":11,"13":12,"14":13,"15":14,"__blank":0},"trail30":{"1":15,"2":1,"3":2,"4":3,"5":4,"6":5,"7":6,"8":7,"9":8,"10":9,"11":10,"12":11,"13":12,"14":13,"15":14,"__blank":0},"trail45":{"1":15,"2":1,"3":2,"4":3,"5":4,"6":5,"7":6,"8":7,"9":8,"10":9,"11":10,"12":11,"13":12,"14":13,"15":14,"__blank":0},"waypoint":{"1":1,"__blank":0},"original":{"0":0,"__blank":1}}; const P=[["trail0",14,296],["trail15",76,217],["trail30",201,145],["trail45",239,64]], D=[[21,393],[27,384],[34,374],[40,365],[47,355],[54,348],[65,343],[75,339],[86,334],[96,330],[106,326],[117,321],[127,317],[120,312],[110,307],[100,303],[89,298],[83,293],[93,289],[104,285],[114,280],[125,276],[135,272],[145,266],[152,257],[159,248],[166,239],[175,233],[186,230],[197,227],[208,224],[219,222],[227,218],[219,209],[212,201],[208,193],[219,191],[230,188],[241,185],[252,182],[263,179],[274,176],[268,171],[259,164],[250,158],[246,152],[257,148],[268,145],[278,141],[289,137],[300,134],[311,130],[322,127],[322,120],[315,111],[319,103],[329,97],[338,90],[347,84],[357,77],[366,71]], MS=100; const tick=()=>{if(new Date().getMinutes()===24){for(const h of [...P.map(p=>p[0]),'waypoint'])slot(h).hide();slot('original')(9,252,V.original[0]);return;}slot('original').hide();
    const m=new Date().getMinutes();
    for(let i=0;i<15*P.length;i+=15){const [h,x,y]=P[i/15];const count=Math.max(0,Math.min(15,m-i));if(count)slot(h)(x,y,V[h][count]);else slot(h).hide();}
    const [x,y]=D[m];slot('waypoint')(x-10,y-10,V.waypoint[1]);
    };   // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { tick(); };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();
    }

